import * as fs from "node:fs";
import * as path from "node:path";
import { exportSessionToHtml, getTemplate } from "../../src/export/html/index";
import type { SessionManager } from "../../src/session/session-manager";

const first = getTemplate();
const removeAssets = process.argv.includes("--remove-assets-after-first-use");
let assetsRemoved = 0;
if (removeAssets) {
	for (const name of fs.readdirSync(import.meta.dir)) {
		if (/^(?:template-[^.]+\.(?:css|html|js)|tool-views\.generated-[^.]+\.js)$/.test(name)) {
			fs.rmSync(path.join(import.meta.dir, name));
			assetsRemoved++;
		}
	}
}
const repeated = getTemplate();
const outputPath = path.join(process.cwd(), "exported-session.html");
const session = {
	getSessionFile: () => path.join(process.cwd(), "probe-session.jsonl"),
	getHeader: () => null,
	getEntries: () => [
		{
			type: "message",
			id: "probe-message",
			parentId: null,
			timestamp: "2026-01-01T00:00:00.000Z",
			message: { role: "user", content: "Exported message in every runtime", timestamp: 0 },
		},
	],
	getLeafId: () => "probe-message",
} as unknown as SessionManager;
await exportSessionToHtml(session, undefined, { outputPath, includeSubSessions: false });
const html = fs.readFileSync(outputPath, "utf8");
const encoded = html.match(/<script id="session-data" type="application\/json">([^<]+)<\/script>/)?.[1];
if (!encoded) throw new Error("Exported HTML has no embedded session");
const data = JSON.parse(Buffer.from(encoded, "base64").toString("utf8"));
if (
	data.entries?.[0]?.message?.content !== "Exported message in every runtime" ||
	!html.includes('id="messages"') ||
	!html.includes('id="theme-select"') ||
	!html.includes("<style>") ||
	!html.includes("--body-bg:") ||
	!html.includes("const THEME_STORAGE_KEY = 'chudcode-export-theme';") ||
	!html.includes("Auto-generated by packages/collab-web/scripts/build-tool-views.ts") ||
	/<template-(?:css|js|tool-views)\/>|<theme-vars\/>|\{\{SESSION_DATA\}\}/.test(html)
) {
	throw new Error("Exported HTML is missing session content or viewer assets");
}

process.stdout.write(JSON.stringify({ stableCache: repeated === first, assetsRemoved }));
